function drawThumb(){const w=root.getElementById('thumbw');if(!w||!origThumb)return;const c=document.createElement('canvas'),sc=Math.min(1,240/Math.max(origThumb.width,origThumb.height));c.width=Math.round(origThumb.width*sc);c.height=Math.round(origThumb.height*sc);c.getContext('2d').drawImage(origThumb,0,0,c.width,c.height);c.id='thumb';w.appendChild(c)}
function onClick(e){const t=e.target;
 if(t.id==='thumb'&&pickMode){const r=t.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*t.width/r.width),y=Math.floor((e.clientY-r.top)*t.height/r.height),d=t.getContext('2d').getImageData(x,y,1,1).data;st.cut.bg=[d[0],d[1],d[2]];pickMode=false;ui();return}
 const pk=t.closest('[data-pick]');if(pk){st.pid=pk.dataset.pick;st.customImg=null;st.cut.bg=null;const p=prod();if(p)defaults(p);origThumb=null;ui();return}
 const s=t.closest('[data-set]');if(s){const k=s.dataset.set,v=s.dataset.v;st[k]=v;if(k==='pal'){st.cbg='';st.cacc=''}if(k==='tpl'){const p=prod();if(p&&/^(card)$/.test(v))st.t.benefit=p.category||'Featured';else if(p&&/^(card)$/.test(st.tpl)){}}ui();return}
 const a=t.closest('[data-act]');if(!a)return;const act=a.dataset.act;
 if(act==='pickbg'){pickMode=!pickMode;ui()}else if(act==='autobg'){st.cut.bg=null;pickMode=false;ui()}else if(act==='nocustom'){st.customImg=null;ui()}else if(act==='resetcol'){st.cbg='';st.cacc='';ui()}
 else if(act==='png')dl('png');else if(act==='pdf')dl('pdf');else if(act==='share')share();else if(act==='qr')qrOnly()}
function onInput(e){const t=e.target,id=t.id||'';
 if(id==='q'){st.q=t.value;root.getElementById('plist').innerHTML=plist();return}
 if(id.startsWith('t_')){st.t[id.slice(2)]=t.value;schedule();return}
 if(t.dataset&&t.dataset.show){st.show[t.dataset.show]=t.checked;schedule();return}
 if(id==='cbg'){st.cbg=t.value;schedule();return}if(id==='cacc'){st.cacc=t.value;schedule();return}
 if(id==='cuton'){st.cut.on=t.checked;schedule();return}
 if(id==='cutshadow'){st.cut.shadow=t.checked;schedule();return}
 if(id==='c_tol'||id==='c_soft'||id==='c_choke'){st.cut[id.slice(2)]=+t.value;const lab=t.previousElementSibling;if(lab)lab.textContent=lab.textContent.replace(/:.*$/,': '+t.value);schedule();return}
 if(id==='base'){st.base=t.value.trim();try{localStorage.setItem(LSK,st.base)}catch(err){}schedule();return}
 if(id==='file'&&t.files&&t.files[0]){const f=t.files[0];if(!/^image\//.test(f.type)){alert('Please choose a photo.');return}const r=new FileReader();r.onload=()=>{st.customImg=r.result;st.cut.bg=null;ui()};r.readAsDataURL(f)}}
/* ---------------- export ---------------- */
const slug=s=>String(s||'poster').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40);
async function fullCanvas(){const {w,h}=SIZES[st.size],c=document.createElement('canvas');c.width=w;c.height=h;await paint(c.getContext('2d'),w,h);return c}
const toBlob=(c,type,q)=>new Promise(r=>c.toBlob(r,type,q));
function save(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000)}
function pdfFrom(jpeg,pw,ph,wpx,hpx){const enc=new TextEncoder(),parts=[],off=[];let len=0;const add=b=>{const u=typeof b==='string'?enc.encode(b):b;parts.push(u);len+=u.length};
 add('%PDF-1.4\n');const obj=(n,body)=>{off[n]=len;add(`${n} 0 obj\n`);add(body);add('\nendobj\n')};
 obj(1,'<</Type/Catalog/Pages 2 0 R>>');obj(2,'<</Type/Pages/Kids[3 0 R]/Count 1>>');obj(3,`<</Type/Page/Parent 2 0 R/MediaBox[0 0 ${pw} ${ph}]/Resources<</XObject<</Im0 4 0 R>>>>/Contents 5 0 R>>`);
 off[4]=len;add(`4 0 obj\n<</Type/XObject/Subtype/Image/Width ${wpx}/Height ${hpx}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${jpeg.length}>>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');
 const cs=`q ${pw} 0 0 ${ph} 0 0 cm /Im0 Do Q`;obj(5,`<</Length ${cs.length}>>\nstream\n${cs}\nendstream`);
 const xr=len;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)add(String(off[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<</Size 6/Root 1 0 R>>\nstartxref\n${xr}\n%%EOF`);
 const out=new Uint8Array(len);let p=0;parts.forEach(u=>{out.set(u,p);p+=u.length});return out}
async function dl(kind){const p=prod();if(!p){alert('Choose a product first.');return}const b=root.querySelector('[data-act="'+kind+'"]');const old=b.textContent;b.textContent='Working…';
 try{const c=await fullCanvas(),name=`dk-${slug(p.name)}-${st.size}`;
  if(kind==='png')save(await toBlob(c,'image/png'),name+'.png');
  else{const jb=await toBlob(c,'image/jpeg',.93),jpeg=new Uint8Array(await jb.arrayBuffer()),pw=595,ph=Math.round(595*c.height/c.width);save(new Blob([pdfFrom(jpeg,pw,ph,c.width,c.height)],{type:'application/pdf'}),name+'.pdf')}}
 catch(e){alert('Could not create the file: '+e.message)}b.textContent=old}
async function share(){const p=prod();if(!p){alert('Choose a product first.');return}try{const c=await fullCanvas(),blob=await toBlob(c,'image/png'),f=new File([blob],`dk-${slug(p.name)}.png`,{type:'image/png'});
  if(navigator.canShare&&navigator.canShare({files:[f]}))await navigator.share({files:[f],title:p.name,text:p.name+' at D&K Beverages'});else{save(blob,f.name);alert('Sharing is not available here, so the image was downloaded instead.')}}catch(e){if(e.name!=='AbortError')alert('Could not share: '+e.message)}}
async function qrOnly(){const p=prod();if(!p){alert('Choose a product first.');return}const c=document.createElement('canvas'),S2=1000;c.width=S2;c.height=S2+140;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);
 const link=st.base.replace(/#.*$/,'').replace(/\/?$/,'/')+'#product='+encodeURIComponent(p.id);window.DKQR.draw(x,link,40,40,S2-80,{fg:'#111',level:'M',quiet:1});x.fillStyle='#111';x.textAlign='center';x.font='700 54px Arial,sans-serif';x.fillText(p.name.slice(0,34),S2/2,S2+40);
 x.font='400 34px Arial,sans-serif';x.fillStyle='#555';x.fillText('Scan to see it on D&K Beverages',S2/2,S2+100);save(await toBlob(c,'image/png'),`dk-qr-${slug(p.name)}.png`)}
