function mount(){const ph=document.getElementById('posterhost');if(!ph)return;if(!HOST)build();if(ph.firstChild===HOST)return;ph.innerHTML='';ph.appendChild(HOST);
 const list=root.getElementById('plist');if(list)list.innerHTML=plist();if(!st.pid&&prods().length){st.pid=prods()[0].id;const p=prod();if(p)defaults(p);ui()}else schedule()}
new MutationObserver(()=>{const ph=document.getElementById('posterhost');if(ph&&(!HOST||ph.firstChild!==HOST))mount()}).observe(document.documentElement,{childList:true,subtree:true});
